import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"消息转换模式（Message Translator）","description":"","frontmatter":{},"headers":[],"relativePath":"integration/message-translator.md","filePath":"integration/message-translator.md","lastUpdated":1791580441000}`),a={name:`integration/message-translator.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="消息转换模式-message-translator" tabindex="-1">消息转换模式（Message Translator） <a class="header-anchor" href="#消息转换模式-message-translator" aria-label="Permalink to “消息转换模式（Message Translator）”">​</a></h1><p>消息转换器从一条通道读消息，按映射规则改写，写进另一条通道：两个系统各自保持自己的消息格式，格式差异由独立的转换组件承担。它出自《Enterprise Integration Patterns》[S10]，要解决的问题是消息格式没有两套系统是相同的——字段名不同、单位不同、编码不同、版本节奏不同。让 A 系统迁就 B 系统，改了一边另一边的老版本又出问题；转换器把&quot;格式怎么变&quot;收进一个组件，收发双方互不迁就。</p><h2 id="常见形态" tabindex="-1">常见形态 <a class="header-anchor" href="#常见形态" aria-label="Permalink to “常见形态”">​</a></h2><ul><li><strong>信封转换（Envelope Wrapper）</strong>：外层协议换装——HTTP 头转消息头、JMS 头转 Kafka header，载荷不动。</li><li><strong>内容增强（Content Enricher）</strong>：消息缺字段，转换器查齐再往下发——订单消息只有用户 ID，增强器补上用户等级。</li><li><strong>内容过滤（Content Filter）</strong>：裁掉下游不需要的字段再转发，减少下游的耦合与敏感数据暴露面。</li><li><strong>规范数据模型（Canonical Data Model）</strong>：n 个系统互转是 n(n-1)/2 套映射，各自转换到统一中间格式只需 2n 套——系统越多省得越多。</li></ul><h2 id="适用与不适用" tabindex="-1">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to “适用与不适用”">​</a></h2><p>适用于：两个系统的格式只能各改各的；历史系统不可动；多系统互连且格式持续演进。</p><p>不适用：</p><ol><li>格式本来一致：直通通道即可，转换器是纯开销。</li><li>格式可以协商统一：能改就改源头，规范模型是&quot;改不动时的止损&quot;，不是首选。</li><li>强一致事务边界内：转换器是异步组件，别指望它参与事务回滚。</li></ol><h2 id="与其他模式的关系" tabindex="-1">与其他模式的关系 <a class="header-anchor" href="#与其他模式的关系" aria-label="Permalink to “与其他模式的关系”">​</a></h2><ul><li>与<a href="/hello-design-patterns/structural/adapter">适配器</a>：同一意图在消息域的形态——适配器改接口调用，转换器改消息体；两者都在&quot;双方都别改&quot;的前提下搭桥。</li><li>与<a href="/hello-design-patterns/integration/message-channel">消息通道</a>、<a href="/hello-design-patterns/integration/message-router">消息路由</a>：转换器是通道上的加工组件，常与路由器串联——先路由到对应的转换分支，再写进输出通道。</li><li>与<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>：远程代理隐藏&quot;调用是跨进程的&quot;，转换器承认&quot;两边格式就是不同&quot;，一个遮掩一个显式管理。</li></ul><h2 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to “关键参数”">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>取值依据</th><th>设错的后果</th></tr></thead><tbody><tr><td>映射规则载体</td><td>代码（MapStruct 类）或配置（映射表）</td><td>规则散落业务代码里，格式演进要全库翻找</td></tr><tr><td>版本策略</td><td>消息带版本号，转换器双版本并存</td><td>只支持最新版本，发布窗口被下游卡死</td></tr><tr><td>失败策略</td><td>schema 校验不过就进死信</td><td>静默丢字段，下游拿到残缺数据</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>Go 实现：订单消息 v1 转 v2——字段改名加单位换算，转换失败返回错误而不是静默放行。</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#F97583;">package</span><span style="color:#B392F0;"> translator</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> (</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">errors</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">fmt</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// V1 旧格式：金额单位是分</span></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> OrderV1</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	OrderID </span><span style="color:#F97583;">string</span></span>
<span class="line"><span style="color:#E1E4E8;">	Amount  </span><span style="color:#F97583;">int64</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// V2 新格式：字段改名，金额单位是元</span></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> OrderV2</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	OrderNo    </span><span style="color:#F97583;">string</span></span>
<span class="line"><span style="color:#E1E4E8;">	AmountYuan </span><span style="color:#F97583;">float64</span></span>
<span class="line"><span style="color:#E1E4E8;">	Schema     </span><span style="color:#F97583;">string</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">var</span><span style="color:#E1E4E8;"> errInvalid </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> errors.</span><span style="color:#B392F0;">New</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;invalid message&quot;</span><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// V1ToV2 映射失败返回错误，不静默放行残缺消息</span></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#B392F0;"> V1ToV2</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">v1</span><span style="color:#B392F0;"> OrderV1</span><span style="color:#E1E4E8;">) (</span><span style="color:#B392F0;">OrderV2</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">	if</span><span style="color:#E1E4E8;"> v1.OrderID </span><span style="color:#F97583;">==</span><span style="color:#9ECBFF;"> &quot;&quot;</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">		return</span><span style="color:#B392F0;"> OrderV2</span><span style="color:#E1E4E8;">{}, fmt.</span><span style="color:#B392F0;">Errorf</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;missing order_id: </span><span style="color:#79B8FF;">%w</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#E1E4E8;">, errInvalid)</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#F97583;">	return</span><span style="color:#B392F0;"> OrderV2</span><span style="color:#E1E4E8;">{</span></span>
<span class="line"><span style="color:#E1E4E8;">		OrderNo:    v1.OrderID,</span></span>
<span class="line"><span style="color:#E1E4E8;">		AmountYuan: </span><span style="color:#F97583;">float64</span><span style="color:#E1E4E8;">(v1.Amount) </span><span style="color:#F97583;">/</span><span style="color:#79B8FF;"> 100</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">		Schema:     </span><span style="color:#9ECBFF;">&quot;order.v2&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">	}, </span><span style="color:#79B8FF;">nil</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><p>Java 侧按场景对号入座：字段映射用 MapStruct（编译期生成映射代码，无反射开销）；Camel 的 <code>transform()</code> 与 <code>marshal().json()</code> 把转换嵌进路由；Spring Integration 的 <code>Transformer</code> 是独立组件形态。</p><h2 id="接入时的三件小事" tabindex="-1">接入时的三件小事 <a class="header-anchor" href="#接入时的三件小事" aria-label="Permalink to “接入时的三件小事”">​</a></h2><ol><li><strong>消息带版本号，转换器双版本并存</strong>：发布窗口两边对不齐是常态，v1→v2 的桥要活到最后一方升级完。</li><li><strong>schema 校验兜底</strong>：转换前后各过一遍 schema 校验，映射失败进死信，绝不静默丢字段。</li><li><strong>规范模型别轻易改</strong>：统一中间格式一旦有 n 个系统接入，改一版就是 n 个转换器联动——变更走版本化，不做原地替换。</li></ol><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/integration/message-channel">消息通道</a>、<a href="/hello-design-patterns/integration/message-router">消息路由</a>：转换器所在的管道。</li><li><a href="/hello-design-patterns/structural/adapter">适配器模式</a>：同一意图在接口域的形态。</li><li><a href="/hello-design-patterns/integration/overview">集成模式导读</a>：本区口径。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S10] Gregor Hohpe、Bobby Woolf，《Enterprise Integration Patterns》，Addison-Wesley，2002。消息转换的原始出处。</li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};